def import_after_last(src, line):
    lines = src.split("\n")
    last = -1
    for i, ln in enumerate(lines):
        if ln.startswith("import "):
            last = i
    if last == -1:
        return src, False
    lines.insert(last + 1, line)
    return "\n".join(lines), True

def main():
    DART_PNG.parent.mkdir(parents=True, exist_ok=True)
    DART_PNG.write_bytes(base64.b64decode(DART_B64))
